INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('4a716408-5c42-4904-a5c2-c14e448bb996', 'radical', '匚', 'cage', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Radikal ini adalah sangkar karena tertutup seluruh sisinya kecuali satu sisi (sisi yang terbuka adalah tempat pintu atau gerbang sangkar berada). Tidak ada apa pun di dalam sangkar ini karena tidak ada gerbangnya, dan apa pun yang ada di dalamnya sudah keluar. Saya harap itu tidak gila...') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('4a716408-5c42-4904-a5c2-c14e448bb996', 'Kandang', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('b4916979-3eaa-496d-9adc-2e741dab5b35', 'radical', '矢', 'arrow', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Anda memiliki senjata yang sangat besar. Mengapa? Karena hanya senjata besar yang bisa menembakkan anak panah! Pelurunya cukup kecil, jadi senjata yang menembakkannya bisa berukuran berapa pun. Namun Anda membutuhkan senjata yang besar jika Anda ingin memasukkan anak panah ke dalamnya dan kemudian menembakkannya ke musuh Anda.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b4916979-3eaa-496d-9adc-2e741dab5b35', 'Panah', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('94882ce8-fa0f-4e68-801d-4d3a50ba7d82', 'radical', '艹', 'flowers', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Lihat hal-hal kecil yang mencuat dari tanah? Hal-hal kecil itu adalah bunga yang sangat kecil. Anda tahu itu bunga dan bukan, katakanlah, rumput, karena letaknya di luar. Anda akan mempelajari rumput nanti, dan jaraknya akan lebih sedikit, tetapi agak mirip dengan ini, jadi ingatlah itu!') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('94882ce8-fa0f-4e68-801d-4d3a50ba7d82', 'Bunga', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('7ff33206-5a31-4613-b72f-679bb129b464', 'radical', '赤', 'red', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Ada beberapa kaki dan sirip di bawah tanah. Bayangkan diri Anda melihat semua anggota tubuh yang terputus ini... ada darah di mana-mana. Tidak peduli seberapa dalam Anda menggali, semuanya berwarna merah.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7ff33206-5a31-4613-b72f-679bb129b464', 'Merah', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('1710cb10-9387-4d67-a53e-1323d2255bbd', 'radical', '丁', 'street', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Ada duri di bawah tanah, menahannya di tempatnya. Ini sebenarnya adalah sebuah jalan. Semua jalan harus diamankan ke tanah dengan duri agar tidak tergelincir ke mana-mana. Jika Anda mencoba memperbaiki jalanan aspal yang kita miliki saat ini, Anda masih akan menemukan duri di bawah tanah untuk menahannya. Semakin banyak Anda tahu! ⭐') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1710cb10-9387-4d67-a53e-1323d2255bbd', 'Jalan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('fc69966b-a1be-464a-9347-ec57baaf1b4c', 'radical', '走', 'run', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Lihat orang itu berlari? Namun, jangan bingung membedakannya dengan kaki (足). Kepalanya hanya terbentur karena orang ini larinya kencang sekali.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('fc69966b-a1be-464a-9347-ec57baaf1b4c', 'Jalankan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('7b060cbe-43d7-42a7-97c8-1029df8bc838', 'radical', '穴', 'hole', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Anda memiliki atap di atas sesuatu yang tampak seperti gunung berapi. Apa penutup atap di puncak gunung berapi? Wah, itu pasti menutupi lubang di bagian atas. Saya kira ada yang mengira jika mereka membangun atap di lubang gunung berapi, tidak ada lahar yang bisa keluar.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7b060cbe-43d7-42a7-97c8-1029df8bc838', 'lubang', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('60b6d463-b6d3-4dc0-83ab-eaa75b4c6999', 'radical', '冫', 'ice', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Ingat kata radikal untuk setetes (cairan)? Ini adalah dua tetes, bukan satu. Saat Anda melihat dua tetes, Anda harus berpikir, "tahap air selanjutnya". Apa tahap selanjutnya? Wah, itu es.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('60b6d463-b6d3-4dc0-83ab-eaa75b4c6999', 'Es', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('1f236699-a1c3-4934-be75-ca79e0705a4d', 'radical', '[Tanduk]', 'horns', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Bisakah kamu melihat tanduknya? Anda bisa memasang tanduk ini pada apa saja. Keledai, manusia, monyet, dan sebagainya. Itulah tepatnya yang akan kita lakukan saat mempelajari kanji yang juga bertanduk.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1f236699-a1c3-4934-be75-ca79e0705a4d', 'Tanduk', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('0412cadb-c5fe-4695-b301-43a191948e55', 'radical', '弓', 'bow', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Radikal ini terlihat seperti busur komposit mewah yang biasa digunakan orang untuk menembak sasaran dan jelas bukan hewan hidup normal. Lihat bagaimana bagian tengahnya ditarik ke belakang? Bayangkan memegang busur ini dan menembakkannya ke sasaran berbentuk monster kepiting aligator raksasa.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('0412cadb-c5fe-4695-b301-43a191948e55', 'Busur', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('0f887859-e31d-4850-ab3b-e9dd12994327', 'radical', '[Tongkat]', 'stick', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Ini adalah tongkat yang mencuat dari tanah. Bahkan terlihat seperti tongkat.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('0f887859-e31d-4850-ab3b-e9dd12994327', 'Tongkat', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('7bb22181-dc64-4fd5-83fa-87570f3ec20b', 'radical', 'ヨ', 'wolverine', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Anda tahu Wolverine dari X-Men? Dia memiliki tiga cakar yang keluar dari tangannya kapan pun dia perlu bertarung, sama sekali tidak berbeda dengan radikal yang Anda lihat di sini.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7bb22181-dc64-4fd5-83fa-87570f3ec20b', 'Serigala', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('d771a7b2-6857-4065-b3f5-f98a15f76ed7', 'radical', '勿', 'wing', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Lihat sayapnya? Ini seperti sayap kelelawar dengan anyaman. Bagaimanapun, itu hanyalah sebuah sayap.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('d771a7b2-6857-4065-b3f5-f98a15f76ed7', 'Sayap', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('62ceff4f-2b23-4900-9058-328daefac46f', 'radical', '勺', 'pool', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Ada setetes air yang terperangkap di penjara. Penjara tempat kita bermain! Itu kolam! Airnya mungkin tidak suka berada di sana, tapi kita semua, orang-orang seksi, pasti menyukainya.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('62ceff4f-2b23-4900-9058-328daefac46f', 'Kolam', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('5d78907c-37d7-4f74-b246-3f9e0d7bdd1b', 'radical', '史', 'history', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Mulut yang berbicara tentang harta karun... bagiku itu terdengar lebih seperti sejarah kuno. Hanya karena ada harta karun yang terkubur di mana-mana dalam sejarah, bukan berarti harta karun itu belum ditemukan sampai saat ini. Jangan biarkan sejarah mengambil alih hidupmu, seperti halnya pemilik mulut ini.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5d78907c-37d7-4f74-b246-3f9e0d7bdd1b', 'Sejarah', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('9785461d-e8e8-4205-b53f-52751eb42543', 'radical', '台', 'machine', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Radikal ini sama dengan kanji. Artinya mesin.
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('9785461d-e8e8-4205-b53f-52751eb42543', 'Mesin', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('e1ddd065-1e0b-4b39-a1dd-3a70fc12c1e5', 'radical', '[Daun]', 'leaf', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Ada daun di atasnya dan ada batang yang turun ke luar, menjadikannya daun radikal. Bentuknya seperti daun teratai, berada di atas air dengan batangnya turun ke dasar tempat kotoran berada.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e1ddd065-1e0b-4b39-a1dd-3a70fc12c1e5', 'Daun', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('8fbd6104-9689-458a-acff-fb1fc83d8d3d', 'radical', '凵', 'box', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Kotak ini terbuka. Mungkin ada banyak hal di dalamnya, tetapi untuk saat ini yang perlu Anda ketahui hanyalah arti dari kata radikal ini, yaitu kotak.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('8fbd6104-9689-458a-acff-fb1fc83d8d3d', 'Kotak', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('8f9aac3c-fd86-444f-832b-74d62f9dd22a', 'radical', '未', 'jet', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Ini seperti salah satu jet yang mempunyai sayap hidung kecil juga. Bayangkan Anda sedang melihat jet dari atas ke bawah, seperti inilah tampilannya. Itu juga mengapa ini disebut jet radikal.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('8f9aac3c-fd86-444f-832b-74d62f9dd22a', 'Jet', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('675b1f3c-9436-4a3f-8561-03765739f388', 'radical', '占', 'fortune', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Seseorang memiliki jari kaki di mulutnya. Mereka adalah peramal yang meramal nasib Anda. Tapi agar dia bisa melakukannya, dia harus mengambil salah satu jari kakimu dan mencicipinya. Ini lebih baik menjadi keberuntungan bagi Anda untuk membiarkan seseorang memasukkan kaki Anda ke dalam mulutnya.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('675b1f3c-9436-4a3f-8561-03765739f388', 'Keberuntungan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('39a4a636-0919-4af1-86bd-bbff8df83f52', 'radical', '氵', 'tsunami', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Anda pernah melihat satu tetes (丶), tetapi apa yang terjadi jika Anda melipatgandakannya dan mendapat tiga tetes, yang merupakan jumlah maksimum tetes yang bisa Anda dapatkan? Anda akan mengalami tsunami dahsyat, karena terlalu banyak air dan tidak ada tempat untuk mengalirkannya. Anggap saja ini sebagai banyak air. Ketika Anda memiliki banyak air, Anda mengalami tsunami.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('39a4a636-0919-4af1-86bd-bbff8df83f52', 'Tsunami', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('363fa573-c74d-4c64-b6e9-7b8ed2fe3482', 'radical', '央', 'center', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Radikal ini sama dengan kanji. Artinya pusat.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('363fa573-c74d-4c64-b6e9-7b8ed2fe3482', 'Pusat', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('414f4410-e437-4711-8b1e-8ad29f789dd7', 'radical', '卩', 'stamp', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Radikal ini bentuknya agak mirip huruf P ya? Itu adalah huruf P yang dicetak pada sesuatu... tunggu, itu tidak dicetak, itu adalah stempel yang ditempel di kertas. Peter Parker suka menggunakan prangko daripada pulpen.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('414f4410-e437-4711-8b1e-8ad29f789dd7', 'Stempel', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('67eadd98-7f40-4d2e-b64b-38f22ce62572', 'kanji', '売', '売', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Ada seorang samurai dengan (hanya) dahi dan kakinya. Segala sesuatu di antaranya hilang. Apa yang terjadi dengan segala sesuatu di antaranya? Dia kekurangan uang, jadi dia harus menjual semuanya, hanya menyisakan bagian atas dan bawah.', 'Jika Anda melihat seorang samurai mencoba menjual seluruh bagian tubuhnya, inilah yang harus Anda katakan, "Sampai jumpa (ばい)!" dan keluar saja dari sana. Sebenarnya, jika ada orang yang mencoba menjual bagian tubuh Anda kepada Anda, Anda mungkin harus mengucapkan selamat tinggal berulang kali sampai Anda bisa menjauh darinya.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('67eadd98-7f40-4d2e-b64b-38f22ce62572', 'Jual', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('67eadd98-7f40-4d2e-b64b-38f22ce62572', 'ばい', 'onyomi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('67eadd98-7f40-4d2e-b64b-38f22ce62572', 'う', 'kunyomi', false) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('42b6568f-aa17-4f17-bfb4-2b3a48433d7c', 'kanji', '住', '住', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Pemimpin para empu mendapat hunian terbesar. Dia tinggal di sebuah rumah besar di puncak gunung, dikelilingi oleh semua tuan lainnya di tempat tinggal mereka yang lebih kecil.', 'Dia membutuhkan tempat tinggal sebesar ini sehingga dia memiliki tempat untuk menyimpan semua perhiasannya (じゅう). Tuan selalu punya banyak barang mewah dan mahal, dan dia punya perhiasan.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
