INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('b6529f1a-cab2-4a58-90a9-c822d4efdc01', 'kanji', '医', '医', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Anda berada di dalam sangkar dan Anda tertembak panah. Jelas segalanya terlihat sangat buruk. Anda memerlukan obat jika Anda ingin hidup.', 'Saat kita perlu mengingat bunyi い kita menggunakan kata "Elang".
