INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('5116cf11-bdc1-4109-b3c8-6a40c74745bc', 'kanji', '者', '者', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Peti mati terlalu lama ditinggalkan di bawah sinar matahari. Saat mayat dijemur di bawah sinar matahari seperti ini, mereka benar-benar mulai membusuk. Namun Anda bertanya-tanya siapa orang ini. Anda tidak dapat mengetahuinya karena terlalu banyak yang hancur. Anda melihat peti mati itu. Ada labelnya, tapi hanya tertulis "seseorang".', 'Untuk mengingat bunyi しゃ kita menggunakan "dukun".
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5116cf11-bdc1-4109-b3c8-6a40c74745bc', 'Seseorang', true) ON CONFLICT DO NOTHING;
