INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('2737017b-d685-4d11-aa96-9c56df70a678', 'kanji', '始', '始', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Jika Anda memberi seorang wanita sebuah mesin, dia akan segera mulai belajar cara menggunakannya. Dia juga akan memulainya sebelum orang lain bisa melakukannya. Wanita sangat pandai menyalakan mesin baru!', 'Sebenarnya, sebelum dia memulai, dia harus mencukur bulu domba (し) di sana. Mesin ini akan mengubah wol menjadi benang, tetapi Anda tidak bisa memulai proses itu hanya dengan memasukkan domba ke dalamnya. Anda harus menjaga domba kecil itu tetap aman!') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
