INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('ce725efa-3022-4eee-a8d3-d0990ae72985', 'kanji', '空', '空', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Memberi kaki atap adalah jenis konstruksi yang Anda lakukan. Anda membuatnya agar atapnya bisa berada di langit. Selain berarti "langit", kanji ini juga sering berarti kosong. Coba pikirkan - tidak ada yang lebih kosong daripada langit!', 'Alasan Anda ingin memasang atap di langit adalah karena atap tersebut menjauhkan semua kuti (くう) yang ada di tanah.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
