INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('f0f62569-831a-4828-82ad-6e5a3422ca56', 'kanji', '夜', '夜', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Seorang pemimpin mengenakan penutup dan berdiri di luar pada musim dingin. Ditambah lagi hujan dan dia berlumuran tetesan air. Terlebih lagi, ini sudah malam.', 'Pertanyaannya adalah, apa yang dia lindungi dari mereka pada malam hari? Ternyata, itu adalah tim bisbol Yankees (や). Mereka kehabisan darah, dan hanya pemimpin yang bisa melindungi kita.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
