INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('0e245655-2560-4142-a1dc-0a699f18db39', 'kanji', '店', '店', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Dahulu kala, seseorang memasang kanopi di atas bilik ramalannya dan mendirikan toko pertama. Toko ini berbasis keberuntungan, tetapi sejak itu banyak toko berbeda bermunculan!', 'Toko ini dengan cepat berubah menjadi sepuluh toko (てん)! Itu adalah ide yang bagus, jadi semua orang yang menjual barang dan jasa memutuskan untuk menirunya dan membuat toko mereka sendiri. Keesokan harinya ada sepuluh lagi.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
