INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('6220bf2d-345c-4972-a039-428012fb6391', 'kanji', '服', '服', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Ambil cap bulan di bangku di depan Anda dan gunakan pada semua pakaian Anda. Sekarang bahkan jika Anda menjual atau kehilangan sepotong pakaian, Anda akan dapat menemukannya lagi dengan memeriksa stempel bulan khusus Anda.', 'Beberapa hari kemudian Anda sedang bersama seorang teman dan Anda mengenali pakaian yang mereka kenakan. Anda mengambilnya, merobeknya, dan berteriak, "F**k (ふく) kamu!" Itu stempel bulanmu! Ini pakaianmu!!') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
