INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4eac7be8-986c-4ddd-8f71-0800c4e73f12', 'この町には、コンビニがおおいです。', 'Ada banyak toko serba ada di kota ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4eac7be8-986c-4ddd-8f71-0800c4e73f12', 'よる、一人でこの町をあるくのはきけんだ。', 'Berbahaya berjalan sendirian di kota ini pada malam hari.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4eac7be8-986c-4ddd-8f71-0800c4e73f12', '私の町は、最高のエアギターを作ることで有名です。', 'Kota saya terkenal sebagai pembuat gitar tak kasat mata terbaik.') ON CONFLICT DO NOTHING;
