INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('21cf4a39-8aab-4c80-a8cf-4e04f73d2b46', 'はな', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('21cf4a39-8aab-4c80-a8cf-4e04f73d2b46', 'ヒマワリは、とてもきれいな花です。', 'Bunga matahari merupakan bunga yang sangat indah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('21cf4a39-8aab-4c80-a8cf-4e04f73d2b46', 'この花の花ことばは、はな毛ボーボーです。', 'Dalam bahasa bunga, yang satu ini berarti bulu hidung yang lebat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('21cf4a39-8aab-4c80-a8cf-4e04f73d2b46', '何か花を使った料理が知りたいんだけど。花のスープとかって聞いたことある？', 'Saya ingin belajar memasak dengan bunga. Pernahkah Anda mendengar tentang sup bunga?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9dfb878a-be94-4738-90b3-ea0fc0f8799a', 'vocabulary', '花火', '花火', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Bunga api... seperti apa bunga yang terbakar? Itu akan menjadi kembang api. Sangat masuk akal, bukan?', 'Bunga api... seperti apa bunga yang terbakar? Itu akan menjadi kembang api. Sangat masuk akal, bukan?') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
