INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9dfb878a-be94-4738-90b3-ea0fc0f8799a', '花火が上がるのはきんよう日だけです。', 'Kembang api hanya akan dinyalakan pada hari Jumat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9dfb878a-be94-4738-90b3-ea0fc0f8799a', '昨日、かぞくで花火大かいに出かけました。', 'Saya pergi melihat pertunjukan kembang api bersama keluarga saya kemarin.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9dfb878a-be94-4738-90b3-ea0fc0f8799a', '花火ってめっちゃいい匂いだよね？', 'Kembang api mempunyai bau yang harum, bukan?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2421763d-64af-4cc8-97df-c46b3ebc17f1', 'vocabulary', '花見', '花見', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Ketika Anda memiliki bunga yang dapat Anda lihat, Anda sedang melihat bunga. Tapi bukan sembarang bunga. Bunga apa yang suka dilihat orang Jepang? Benar sekali, kata ini mengacu pada melihat bunga sakura.', 'Ketika Anda memiliki bunga yang dapat Anda lihat, Anda sedang melihat bunga. Tapi bukan sembarang bunga. Bunga apa yang suka dilihat orang Jepang? Benar sekali, kata ini mengacu pada melihat bunga sakura.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
