INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2421763d-64af-4cc8-97df-c46b3ebc17f1', 'ことしは花見にいかなかった。', 'Saya tidak pergi melihat sakura tahun ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2421763d-64af-4cc8-97df-c46b3ebc17f1', '北りくち方の花見の名しょをごしょうかいします。', 'Saya akan memperkenalkan Anda pada tempat melihat bunga sakura terbaik di wilayah Hokuriku.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2421763d-64af-4cc8-97df-c46b3ebc17f1', '死ぬ前にもう一度花見をしながら宴会がしたいなあ。', 'Sebelum aku mati, aku ingin mengadakan pesta minum di bawah bunga sakura sekali lagi.') ON CONFLICT DO NOTHING;
