INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9b376ace-a649-48a8-a45e-99f3be315581', 'その赤のくつをとってください。', 'Silakan ambil sepatu merahnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9b376ace-a649-48a8-a45e-99f3be315581', 'つぎは、まえがみのいろを赤にしようとおもっています。', 'Aku sedang berpikir untuk mewarnai poniku dengan warna merah lain kali.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9b376ace-a649-48a8-a45e-99f3be315581', 'オーランド・ブルームという名前を聞くだけで、今でも頬が赤くなる。', 'Pipiku masih merona saat mendengar nama Orlando Bloom.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d04aadb6-c5bd-4b26-adcf-02aa13c3088e', 'vocabulary', '赤ちゃん', '赤ちゃん', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'ちゃん adalah sebutan kehormatan yang Anda berikan pada nama anak. Jadi, siapakah anak misterius yang kamu panggil merah ini? Saat bayi lahir, apa warnanya? Anda mengerti, semuanya berwarna merah. Dan, karena kamu ingin menjadi baik dan imut, kamu menambahkan ちゃん ke dalamnya. Itu sebabnya あかちゃん masih bayi.', 'ちゃん adalah sebutan kehormatan yang Anda berikan pada nama anak. Jadi, siapakah anak misterius yang kamu panggil merah ini? Saat bayi lahir, apa warnanya? Anda mengerti, semuanya berwarna merah. Dan, karena kamu ingin menjadi baik dan imut, kamu menambahkan ちゃん ke dalamnya. Itu sebabnya あかちゃん masih bayi.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
