INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('92673caf-92fc-4a73-ac71-46df0fdb7f70', 'ちょっとは空気をよんでください。', 'Tolong ambil saja petunjuknya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('92673caf-92fc-4a73-ac71-46df0fdb7f70', '冬のあさの空気はつめたい。', 'Udara pagi musim dingin terasa dingin.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('92673caf-92fc-4a73-ac71-46df0fdb7f70', '海賊の宇宙船に乗っている猿は、三時間後に大気圏に突入する予定だ。猿は、肺に好きなだけ空気を吸い込むことが待ちきれない。', 'Monyet di kapal luar angkasa bajak laut akan memasuki kembali atmosfer dalam 3 jam. Dia tidak sabar untuk memasukkan udara sebanyak mungkin ke dalam paru-parunya.') ON CONFLICT DO NOTHING;
