INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9feb5d6d-afe8-4c34-91dc-56f6007ecd47', '空にきれいなにじがかかっている。', 'Ada pelangi yang indah di langit.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9feb5d6d-afe8-4c34-91dc-56f6007ecd47', '女心とあきの空といいますが、男心だってかわりやすいんですよ。', 'Mereka mengatakan bahwa pikiran wanita dan langit musim gugur berubah dengan cepat, namun pikiran pria juga berubah dengan cepat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9feb5d6d-afe8-4c34-91dc-56f6007ecd47', '今夜映画E.T.の有名なシーンがちゃんと見れるくらい、空が晴れ渡っているといいんだが。', 'Saya berharap langit malam ini cukup cerah sehingga kita dapat melihat adegan terkenal dari film E.T.') ON CONFLICT DO NOTHING;
