INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('86bf59b1-cbfd-405b-8893-11939f7c79c7', 'きのうの夜、パーティーに行きました。', 'Saya pergi ke pesta tadi malam.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('86bf59b1-cbfd-405b-8893-11939f7c79c7', 'きのうの夜は、こうふんしてほとんどねむれませんでした。', 'Tadi malam, saya sangat bersemangat sehingga saya hampir tidak bisa tidur.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('86bf59b1-cbfd-405b-8893-11939f7c79c7', '夜には、モンスターたちが床から這い上がり、私のベッドの下でお茶会を開くんだよ。', 'Malam hari adalah waktu ketika monster merangkak naik ke lantai untuk mengadakan pesta teh di bawah tempat tidurku.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('afb51a78-2429-462c-a4ba-7d267b688216', 'vocabulary', '今夜', '今夜', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Malam sekarang adalah malam saat ini alias malam ini.', 'Malam sekarang adalah malam saat ini alias malam ini.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
