INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('be92ddf1-fc03-403a-844e-43fe3cb2323d', 'えきからその店までの地図をかいてください。', 'Silakan menggambar peta dari stasiun ke toko.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('be92ddf1-fc03-403a-844e-43fe3cb2323d', 'この店は年内はすでにずっとよやくでいっぱいだ。', 'Restoran sudah penuh dipesan untuk sisa tahun ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('be92ddf1-fc03-403a-844e-43fe3cb2323d', 'この店のこと絶対気に入るぜ。世界一うまいミートローフがあるんだよ。', 'Anda akan menyukai toko ini. Mereka memiliki daging cincang terbaik di dunia.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('77bc74ae-519c-40cc-bbcf-f777b3d69579', 'vocabulary', '明るい', '明るい', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Ini adalah kanji tunggal ditambah hiragana るい. Kata-kata yang diakhiri dengan い biasanya merupakan kata sifat, dan ini tidak terkecuali. Apa bentuk kata sifat dari terang? Itu juga cerah.', 'Ini adalah kanji tunggal ditambah hiragana るい. Kata-kata yang diakhiri dengan い biasanya merupakan kata sifat, dan ini tidak terkecuali. Apa bentuk kata sifat dari terang? Itu juga cerah.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
