INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('77bc74ae-519c-40cc-bbcf-f777b3d69579', 'このへやは明るい。', 'Ruangan ini terang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('77bc74ae-519c-40cc-bbcf-f777b3d69579', 'トーフグのみんなは明るい。', 'Semua orang di Tofugu ceria.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('77bc74ae-519c-40cc-bbcf-f777b3d69579', '未来はまだまだ明るいよ、おじいちゃん。', 'Masa depanmu masih cerah, Kakek.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2fdeb580-3325-4a71-81d8-efe4ed52e948', 'vocabulary', '不明', '不明', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Sesuatu yang tidak terang akan berawan dan kabur. Apa yang Anda pikirkan saat melihat ke dalam awan kabur? Ini adalah sesuatu yang tidak diketahui, tidak jelas, dan tidak pasti.', 'Sesuatu yang tidak terang akan berawan dan kabur. Apa yang Anda pikirkan saat melihat ke dalam awan kabur? Ini adalah sesuatu yang tidak diketahui, tidak jelas, dan tidak pasti.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
