INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('4de6b8aa-21b4-4a62-8cb7-52fc06e11e1b', 'To Reside', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('4de6b8aa-21b4-4a62-8cb7-52fc06e11e1b', 'すむ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4de6b8aa-21b4-4a62-8cb7-52fc06e11e1b', 'わたしは、父と母と一しょに住んでいます。', 'Saya tinggal bersama ayah dan ibu saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4de6b8aa-21b4-4a62-8cb7-52fc06e11e1b', '青木ヶ原のじゅ海は、住むにはおそろしすぎる場所です。', 'Jukai Aokigahara adalah tempat yang menakutkan untuk ditinggali.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4de6b8aa-21b4-4a62-8cb7-52fc06e11e1b', 'ホビットの穴に住んでみたいのですが、どうやって掘ればいいのか分かりません。', 'Aku ingin tinggal di lubang hobbit, tapi aku tidak tahu cara menggalinya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3c5a5de9-8ce3-41a7-a57a-39024fd73b13', 'vocabulary', '住人', '住人', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Orang yang tinggal di suatu tempat tinggal adalah seseorang yang tinggal di tempat tinggal itu. Mereka adalah penduduk.', 'Orang yang tinggal di suatu tempat tinggal adalah seseorang yang tinggal di tempat tinggal itu. Mereka adalah penduduk.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
