INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('3c5a5de9-8ce3-41a7-a57a-39024fd73b13', 'Dweller', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('3c5a5de9-8ce3-41a7-a57a-39024fd73b13', 'じゅうにん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3c5a5de9-8ce3-41a7-a57a-39024fd73b13', 'こんなしん夜に大声でけんかをしたら、近りんの住人にめいわくだろう。', 'Jika Anda berdebat dengan suara keras hingga larut malam, Anda akan mengganggu tetangga Anda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3c5a5de9-8ce3-41a7-a57a-39024fd73b13', '話し合いの末、森の住人とみずうみの住人は、一しょに百本のけんを買うことにした。', 'Setelah membicarakannya, penghuni hutan dan penghuni danau sepakat untuk membeli 100 pedang bersama.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3c5a5de9-8ce3-41a7-a57a-39024fd73b13', '私は地球の住人です。パーティーにようこそ。', 'Saya adalah penduduk planet Bumi. Selamat datang di pesta.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0557f416-b9b8-4728-8cb5-7aceb898d048', 'vocabulary', '医大', '医大', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Anda pernah melihat 大学 berarti "perguruan tinggi". Jadi ambil 大 dan masukkan ke dalam obat untuk mendirikan "perguruan tinggi kedokteran", atau universitas kedokteran.', 'Anda pernah melihat 大学 berarti "perguruan tinggi". Jadi ambil 大 dan masukkan ke dalam obat untuk mendirikan "perguruan tinggi kedokteran", atau universitas kedokteran.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
