INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d9ada6ff-a770-4304-a448-d29cb60f0198', 'わたしは、医大を目ざしてべん強しています。', 'Saya sedang belajar untuk masuk ke sekolah kedokteran.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d9ada6ff-a770-4304-a448-d29cb60f0198', '医者のたまごをかれ氏にするため、医大生のふりをして、医大にせん入してみました。', 'Saya berpura-pura menjadi mahasiswa kedokteran dan menyelinap ke sekolah kedokteran untuk mencari calon pacar dokter.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d9ada6ff-a770-4304-a448-d29cb60f0198', '私は、ポケモンコレクションを売って、医大の学費を払った。', 'Saya membayar biaya sekolah kedokteran dengan menjual koleksi Pokémon saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('271daf40-fc05-45d5-999a-f12f6629ba5a', 'vocabulary', '医学', '医学', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Ilmu kedokteran adalah ilmu kedokteran. Bisa juga disebut kedokteran, tapi pastikan untuk menganggapnya sebagai "obat" yang ada hubungannya dengan "ilmu kedokteran".', 'Ilmu kedokteran adalah ilmu kedokteran. Bisa juga disebut kedokteran, tapi pastikan untuk menganggapnya sebagai "obat" yang ada hubungannya dengan "ilmu kedokteran".') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('271daf40-fc05-45d5-999a-f12f6629ba5a', 'Ilmu Kedokteran', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('271daf40-fc05-45d5-999a-f12f6629ba5a', 'Medicine', false) ON CONFLICT DO NOTHING;
