INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('271daf40-fc05-45d5-999a-f12f6629ba5a', 'さい近は、医学の本を月に三さつぐらいよんでいます。', 'Akhir-akhir ini, saya membaca sekitar tiga buku ilmu kedokteran dalam sebulan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('271daf40-fc05-45d5-999a-f12f6629ba5a', 'わたしの兄は、医学ぶを目ざしています。', 'Kakak laki-laki saya sedang mencoba masuk ke sekolah kedokteran.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('271daf40-fc05-45d5-999a-f12f6629ba5a', '医学はいつも最新の薬を発見し続けている。昨日は、医者が皿洗いをするようになる薬を私にくれたよ。', 'Ilmu kedokteran selalu menemukan pengobatan baru. Baru kemarin dokter saya memberi saya pil yang bisa membuat saya bisa mencuci piring.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('97c3c68f-17a3-4fa0-ac6c-5feb303d8bcc', 'vocabulary', '医者', '医者', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Seseorang yang bekerja di bidang kedokteran adalah seorang dokter.', 'Seseorang yang bekerja di bidang kedokteran adalah seorang dokter.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
