INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('97c3c68f-17a3-4fa0-ac6c-5feb303d8bcc', 'いしゃ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('97c3c68f-17a3-4fa0-ac6c-5feb303d8bcc', '今日は医者に行かなくちゃいけない。', 'Saya harus pergi ke dokter hari ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('97c3c68f-17a3-4fa0-ac6c-5feb303d8bcc', 'ある夜、とあるあやしいレストランに、もくもくとサメを食べる三人の医者がいました。', 'Suatu malam, di sebuah restoran yang teduh, ada tiga dokter yang mengisi diri mereka dengan ikan hiu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('97c3c68f-17a3-4fa0-ac6c-5feb303d8bcc', '僕は医者になりたいけど、人に触ることが嫌いなんだ。それってやっぱり問題かな？', 'Aku ingin menjadi dokter, tapi aku benci menyentuh orang. Apakah menurut Anda itu akan menjadi masalah?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e16b73a7-5455-40d3-8900-4e91b53bd151', 'vocabulary', '究明', '究明', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Ketika Anda mencerahkan penelitian Anda, itu seperti Anda menyorotinya. Untuk melakukan itu, Anda harus melakukan penyelidikan. 
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e16b73a7-5455-40d3-8900-4e91b53bd151', 'Investigasi', true) ON CONFLICT DO NOTHING;
