INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e16b73a7-5455-40d3-8900-4e91b53bd151', 'お前は本当にしんそうを究明するつもりがあるのか？', 'Apakah Anda benar-benar akan menyelidiki kebenarannya?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e16b73a7-5455-40d3-8900-4e91b53bd151', 'コウイチのおかしな言どうのしんのどうきはまだ究明されていない。', 'Motif sebenarnya di balik perkataan dan perbuatan aneh Koichi belum terungkap.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e16b73a7-5455-40d3-8900-4e91b53bd151', '私が大学で取っている授業の一つで、現在「鳥が先か卵が先か」について究明しているんです。', 'Salah satu mata kuliah yang saya ambil di perguruan tinggi saat ini sedang menyelidiki apakah ayam atau telur lebih dulu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6e01c1f1-4dca-4aee-a3b9-ccd0e2e9f479', 'vocabulary', '作者', '作者', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Seseorang yang membuat adalah seseorang yang menciptakan sesuatu. Dulu, pencipta seperti ini mungkin dikenal dengan banyak hal, namun yang paling menonjol adalah seorang penulis.', 'Seseorang yang membuat adalah seseorang yang menciptakan sesuatu. Dulu, pencipta seperti ini mungkin dikenal dengan banyak hal, namun yang paling menonjol adalah seorang penulis.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
