INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6e01c1f1-4dca-4aee-a3b9-ccd0e2e9f479', 'この小せつの作者の名前がどうしても思い出せません。', 'Saya tidak dapat mengingat nama penulis novel ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6e01c1f1-4dca-4aee-a3b9-ccd0e2e9f479', 'ついにテキストフグの作者に会えました。', 'Kami akhirnya bisa bertemu dengan penulis TextFugu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6e01c1f1-4dca-4aee-a3b9-ccd0e2e9f479', '俺の兄貴がギリシャ神話の作者だったんだが、今は失業している。', 'Kakakku adalah seorang penulis mitologi Yunani, tapi sekarang dia menganggur.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('16058998-d743-432a-a5e1-16d74c7abeff', 'vocabulary', '学者', '学者', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Seseorang yang belajar untuk mencari nafkah. Itu adalah seorang sarjana.', 'Seseorang yang belajar untuk mencari nafkah. Itu adalah seorang sarjana.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
