INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('16058998-d743-432a-a5e1-16d74c7abeff', 'かれのお父さんは、立ぱな学者です。', 'Ayahnya adalah seorang sarjana yang hebat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('16058998-d743-432a-a5e1-16d74c7abeff', 'あの学者はけいれきさしょうをしています。', 'Sarjana itu adalah pemalsu resume.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('16058998-d743-432a-a5e1-16d74c7abeff', '私は世界でも有名なハロー・キティ学者です。', 'Saya seorang sarjana Hello Kitty yang terkenal di dunia.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1c982d7e-5e04-470d-b9c6-945ae5002b28', 'vocabulary', '工学者', '工学者', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Apakah Anda ingat 工学 dari beberapa level yang lalu? Ini adalah seseorang yang ada di 工学. Jika 工学 adalah "rekayasa" maka 工学者 adalah seorang insinyur.', 'Apakah Anda ingat 工学 dari beberapa level yang lalu? Ini adalah seseorang yang ada di 工学. Jika 工学 adalah "rekayasa" maka 工学者 adalah seorang insinyur.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
