INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('1c982d7e-5e04-470d-b9c6-945ae5002b28', 'こうがくしゃ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1c982d7e-5e04-470d-b9c6-945ae5002b28', '「ルンバ」をはつ明したロボット工学者はだれですか？', 'Siapa insinyur robotika yang menemukan Roomba?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1c982d7e-5e04-470d-b9c6-945ae5002b28', 'あの工学者のことはきらいですが、そうするべきだと思ったから、助けてあげました。', 'Saya membantu insinyur itu, meskipun saya tidak menyukainya, karena menurut saya itu adalah hal yang benar untuk dilakukan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1c982d7e-5e04-470d-b9c6-945ae5002b28', '工学者になるためには、長期間勉強をする必要があります。', 'Untuk menjadi seorang insinyur, Anda harus belajar berjam-jam.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('279b39f4-6b1f-4c48-beaf-0b7f1e1ea8da', 'vocabulary', '空間', '空間', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Interval langit adalah luas langit. Di tempat yang hanya berupa langit kosong, yang ada hanyalah ruang. Tentu saja, tidak secara teknis... ada sesuatu di sana, tapi dulu ketika kanji dibuat, tidak ada yang tahu itu. Kata ini dapat berarti ruang dalam kaitannya dengan ruang luar maupun ruang di sekitar Anda di dalam kamar Anda.', 'Interval langit adalah luas langit. Di tempat yang hanya berupa langit kosong, yang ada hanyalah ruang. Tentu saja, tidak secara teknis... ada sesuatu di sana, tapi dulu ketika kanji dibuat, tidak ada yang tahu itu. Kata ini dapat berarti ruang dalam kaitannya dengan ruang luar maupun ruang di sekitar Anda di dalam kamar Anda.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('279b39f4-6b1f-4c48-beaf-0b7f1e1ea8da', 'Ruang', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('279b39f4-6b1f-4c48-beaf-0b7f1e1ea8da', 'くうかん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('279b39f4-6b1f-4c48-beaf-0b7f1e1ea8da', 'あの人と同じ空間にいるだけで心がいやされるんです。', 'Berada di ruang yang sama dengan orang tersebut dapat menyembuhkan hati Anda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('279b39f4-6b1f-4c48-beaf-0b7f1e1ea8da', '日本人の中には、ベビーカーは空間をたくさんとるので、まんいん電車ではきん止にするべきだとかんがえる人もいます。', 'Beberapa orang Jepang berpendapat bahwa kereta dorong bayi sebaiknya dilarang di kereta yang penuh sesak karena memakan banyak tempat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('279b39f4-6b1f-4c48-beaf-0b7f1e1ea8da', '宇宙空間には空気がないけど、それでもやっぱり月に住みたい。', 'Meski tak ada udara di luar angkasa, aku tetap ingin tinggal di bulan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('64047cd7-7507-4f55-b3da-575ddaf2e726', 'vocabulary', '事', '事', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Selain itu di atas segalanya ada makna materi dan tindakan juga. Seperti kanji, kata ini berkaitan dengan tindakan... hal-hal yang Anda lakukan, misalnya, bukan hal-hal fisik.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Selain itu di atas segalanya ada makna materi dan tindakan juga. Seperti kanji, kata ini berkaitan dengan tindakan... hal-hal yang Anda lakukan, misalnya, bukan hal-hal fisik.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
