INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('64047cd7-7507-4f55-b3da-575ddaf2e726', 'スモモさんが、ピンク色のいしょうをきる事が多いのはなぜですか？', 'Menurut Anda mengapa Bu Sumomo memakai begitu banyak pakaian berwarna pink?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('64047cd7-7507-4f55-b3da-575ddaf2e726', '後はいが言っている事がいつもよく分からなくてこまっています。', 'Saya sering kesulitan memahami apa yang dikatakan rekan junior saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('64047cd7-7507-4f55-b3da-575ddaf2e726', 'すまないが、ちょっと今はする事がたくさんあって、忙しいんだ。', 'Maaf, tapi akhir-akhir ini aku sibuk karena ada banyak hal yang harus kulakukan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('16b22688-f8b3-4c03-81d3-921a7b3aeb8b', 'vocabulary', '用事', '用事', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Tindakan tugas adalah sesuatu yang harus Anda lakukan (karena 事 adalah tentang tindakan). Namun, apa cara lain untuk mengatakan "suatu tindakan yang merupakan tugas"? Saya akan mengatakan tugas atau bahkan bisnis.', 'Tindakan tugas adalah sesuatu yang harus Anda lakukan (karena 事 adalah tentang tindakan). Namun, apa cara lain untuk mengatakan "suatu tindakan yang merupakan tugas"? Saya akan mengatakan tugas atau bahkan bisnis.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
