INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('16b22688-f8b3-4c03-81d3-921a7b3aeb8b', 'ようじ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('16b22688-f8b3-4c03-81d3-921a7b3aeb8b', '用事をおねがいしてもいいですか。', 'Apakah Anda keberatan jika saya meminta Anda melakukan beberapa tugas?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('16b22688-f8b3-4c03-81d3-921a7b3aeb8b', 'ごめんなさい！ちょっと用事が出来てしまって、今日のレッスンをキャンセルしないといけなくなってしまいました。', 'Maaf! Aku harus mengurus sesuatu dan aku harus membatalkan pelajaranku hari ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('16b22688-f8b3-4c03-81d3-921a7b3aeb8b', '大事な用事があるので、明日は出勤することができません。', 'Saya ada urusan penting yang harus diselesaikan jadi saya tidak bisa bekerja besok.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('23f6d2bd-fd39-4c1f-98c5-eeb64b999a88', 'vocabulary', '工事', '工事', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Tindakan industri adalah hal-hal yang dilakukan industri. Tindakan industri menciptakan banyak sekali pembangunan, baik itu pembangunan barang, pembangunan jalan, pabrik, dan lain-lain.', 'Tindakan industri adalah hal-hal yang dilakukan industri. Tindakan industri menciptakan banyak sekali pembangunan, baik itu pembangunan barang, pembangunan jalan, pabrik, dan lain-lain.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('23f6d2bd-fd39-4c1f-98c5-eeb64b999a88', 'Konstruksi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('23f6d2bd-fd39-4c1f-98c5-eeb64b999a88', 'こうじ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('23f6d2bd-fd39-4c1f-98c5-eeb64b999a88', 'きのうてつ夜で仕事だったんですが、朝から工事の音がうるさくてぜんぜんねむれてないんです。', 'Saya bekerja sepanjang malam tadi malam, tetapi saya belum bisa tidur sama sekali karena konstruksi berisik yang dimulai pagi ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('23f6d2bd-fd39-4c1f-98c5-eeb64b999a88', '町中で一日中工事しているので、通行止めだらけでいやになるよ。', 'Karena ada pembangunan yang berlangsung sepanjang hari, di seluruh kota, ada banyak jalan yang ditutup di mana-mana dan saya muak dan bosan karenanya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('23f6d2bd-fd39-4c1f-98c5-eeb64b999a88', 'この工事は今日終わったんですよね？', 'Konstruksi ini selesai hari ini, kan?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e60c6961-296d-4e86-93fc-41b5c7a68f33', 'vocabulary', '大事', '大事', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Tindakan besar berarti sesuatu yang besar sedang terjadi. Ini bukanlah tindakan biasa. Ini adalah tindakan yang penting.', 'Tindakan besar berarti sesuatu yang besar sedang terjadi. Ini bukanlah tindakan biasa. Ini adalah tindakan yang penting.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
