INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('704418c4-de8f-4e53-ad99-2d61b39b6b5c', 'しょくじ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('704418c4-de8f-4e53-ad99-2d61b39b6b5c', '今、食事中なので、後でまたかけます。', 'Saya sedang makan, jadi saya akan menelepon Anda lagi nanti.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('704418c4-de8f-4e53-ad99-2d61b39b6b5c', 'どうぞごゆっくりお食事をお楽しみください。', 'Silakan bersantai dan nikmati makanan Anda!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('704418c4-de8f-4e53-ad99-2d61b39b6b5c', 'もし残りの人生毎日同じ食事しか食べられないとしたら、何を選びますか？', 'Jika kamu hanya boleh makan satu kali setiap hari selama sisa hidupmu, apa yang akan kamu pilih?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0cf65c33-b8ce-410d-b6e1-4f475373772a', 'vocabulary', '使う', '使う', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji sendiri artinya menggunakan jadi versi verbanya adalah menggunakan. Jika Anda berbicara tentang uang, ini juga bisa berarti membelanjakan.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji sendiri artinya menggunakan jadi versi verbanya adalah menggunakan. Jika Anda berbicara tentang uang, ini juga bisa berarti membelanjakan.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
