INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0cf65c33-b8ce-410d-b6e1-4f475373772a', '友だちのじしょを使いたいです。', 'Saya ingin menggunakan kamus teman saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0cf65c33-b8ce-410d-b6e1-4f475373772a', 'いたいのはとても苦手なので、ますいを使ってください。', 'Saya tidak pandai menangani rasa sakit, jadi tolong gunakan obat bius.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0cf65c33-b8ce-410d-b6e1-4f475373772a', 'そんなに屁っ放り腰にならないで！知ってる日本語をできるだけ使うようにしなよ。', 'Jangan takut akan hal itu. Anda harus menggunakan bahasa Jepang yang Anda tahu sebanyak mungkin.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b50191d7-4ac5-46f0-bee1-de32542808c6', 'vocabulary', '始める', '始める', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji sendiri artinya memulai atau memulai, dan versi verbanya adalah memulai, memulai sesuatu, memulai, atau memulai sesuatu.
