INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b50191d7-4ac5-46f0-bee1-de32542808c6', '何から始めるのがいいのか、分かりません。', 'Saya tidak tahu harus mulai dari mana.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b50191d7-4ac5-46f0-bee1-de32542808c6', 'むすめさん、四年生になったら、何かならい事を始めるの？', 'Akankah putri Anda memulai ekstrakurikuler ketika dia mencapai kelas empat?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b50191d7-4ac5-46f0-bee1-de32542808c6', '生地をフライパンに流し始める前に、材料を全て混ぜる必要があります。', 'Anda perlu mencampur semua bahan menjadi satu sebelum Anda dapat mulai memindahkan adonan ke dalam panci.') ON CONFLICT DO NOTHING;
