INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b1a9a5c6-8d67-4ee6-b158-8e9e97b5cdfc', 'そのえいがは何時から始まりますか。', 'Jam berapa filmnya dimulai?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b1a9a5c6-8d67-4ee6-b158-8e9e97b5cdfc', 'アメリカと中国のしれつなけいざいせんそうが始まりました。', 'Perang ekonomi sengit antara Amerika dan Tiongkok telah dimulai.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b1a9a5c6-8d67-4ee6-b158-8e9e97b5cdfc', '銃声が、大食いパイコンテストの始まりの合図となります。', 'Suara senapan menandakan lomba makan pie telah dimulai.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a7aa654c-47a3-487a-b43d-2e3e6cc880ca', 'vocabulary', '始めに', '始めに', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Anda tahu bagian kanji artinya dimulai. Tanda に di akhir mengacu pada arah. Jadi, anggaplah ini seperti "arah permulaan" yang merupakan awal mula segala sesuatunya. Itu sebabnya kata/frasa ini berarti "pada mulanya".', 'Anda tahu bagian kanji artinya dimulai. Tanda に di akhir mengacu pada arah. Jadi, anggaplah ini seperti "arah permulaan" yang merupakan awal mula segala sesuatunya. Itu sebabnya kata/frasa ini berarti "pada mulanya".') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
