INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('a7aa654c-47a3-487a-b43d-2e3e6cc880ca', 'はじめに', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a7aa654c-47a3-487a-b43d-2e3e6cc880ca', 'このもんだいでは、始めにしつもんをきいてください。', 'Untuk soal ini, silakan mulai dengan mendengarkan pertanyaannya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a7aa654c-47a3-487a-b43d-2e3e6cc880ca', '始めにカナエがたん生日ケーキにしょうゆをこぼしてしまったこと以外は、コウイチのサプライズバースデーパーティーは大せいこうでした。', 'Pesta ulang tahun kejutan Koichi berjalan sangat baik kecuali Kanae yang menumpahkan kecap asin pada kue ulang tahunnya pada awalnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a7aa654c-47a3-487a-b43d-2e3e6cc880ca', '聖書の一番始めには何が書かれているの？', 'Apa kata pertama di awal Alkitab?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f58f9e6d-fda2-4c2f-b1ac-291fc9310363', 'vocabulary', '服', '服', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
