INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('f58f9e6d-fda2-4c2f-b1ac-291fc9310363', 'ふく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f58f9e6d-fda2-4c2f-b1ac-291fc9310363', '服を引き出しの中に入れてください。', 'Silakan masukkan pakaian Anda ke dalam laci.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f58f9e6d-fda2-4c2f-b1ac-291fc9310363', 'かわいい！おそろいの服をきてるんですね。', 'Lucu sekali! Mereka mengenakan pakaian yang serasi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f58f9e6d-fda2-4c2f-b1ac-291fc9310363', '今日はチョー暑くて、あなたはあまりにも多くの服を着ているよ。', 'Hari ini panas sekali. Anda mengenakan terlalu banyak pakaian.') ON CONFLICT DO NOTHING;
