INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b8b911f2-2656-44c9-ade9-b36c01c901f6', 'マサルさんが持っている物は何ですか。', 'Benda apa yang dimiliki Masaru itu?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b8b911f2-2656-44c9-ade9-b36c01c901f6', 'うちのワンちゃんを物あつかいしないでください！', 'Jangan perlakukan anjingku seperti itu!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b8b911f2-2656-44c9-ade9-b36c01c901f6', '私の好きな物を三つ挙げるなら、チキンと揚げ物とご飯です。', 'Tiga hal favorit saya adalah ayam, gorengan, dan nasi.') ON CONFLICT DO NOTHING;
