INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('66284e0f-2523-4365-95d3-786ad75c0f14', 'さい近のCGは、パッと見たかんじ本物にしか見えないのがマジですごいと思う。', 'CG saat ini sangat realistis sehingga terasa nyata pada pandangan pertama, dan menurut saya itu sangat keren.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('66284e0f-2523-4365-95d3-786ad75c0f14', 'トーフグが本物そっくりのにせ札を作っているという黒いうわさをききました。', 'Saya mendengar rumor kelam bahwa Tofugu membuat uang palsu yang terlihat persis seperti aslinya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('66284e0f-2523-4365-95d3-786ad75c0f14', '小さいころ、父さんはいつも僕に「本物の男は誠実でいつづける」って言ってたけど、結局浮気をして、両親は離婚することになったんだ。', 'Saat aku masih kecil, ayahku selalu bilang padaku bahwa pria sejati tetap setia, tapi dia akhirnya selingkuh dari ibuku dan sekarang mereka akan bercerai.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('810b38d7-aa06-4906-8d50-7f65c2fc747d', 'vocabulary', '名物', '名物', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Yang terkenal dari suatu daerah adalah produknya yang terkenal, tetapi dalam bahasa Inggris akan terdengar lebih baik jika dikatakan itu adalah makanan khas setempat. Saat Anda bepergian keliling Jepang, pastikan untuk mencari 名物! Itu selalu menyenangkan.', 'Yang terkenal dari suatu daerah adalah produknya yang terkenal, tetapi dalam bahasa Inggris akan terdengar lebih baik jika dikatakan itu adalah makanan khas setempat. Saat Anda bepergian keliling Jepang, pastikan untuk mencari 名物! Itu selalu menyenangkan.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
