INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('70fa2198-1222-432a-8ce7-9857957a3f33', '物語の主人公にでもなったつもりでいるんだろう。', 'Saya pikir dia bertindak seolah-olah dia adalah karakter utama sebuah cerita.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('70fa2198-1222-432a-8ce7-9857957a3f33', '竹とり物語は日本の有名な物語です。', 'Kisah Pemotong Bambu adalah legenda Jepang yang terkenal.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('70fa2198-1222-432a-8ce7-9857957a3f33', '今物語を書いているんです。悲しい子犬フェチの男の話です。', 'Saya sedang menulis cerita sekarang. Ini tentang seorang pria sedih yang terobsesi dengan anak anjing.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d5bd929f-f589-4be3-930b-7e43b9d2f317', 'vocabulary', '注ぐ', '注ぐ', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya menuangkan jadi versi vocab verbanya adalah menuangkan.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya menuangkan jadi versi vocab verbanya adalah menuangkan.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('d5bd929f-f589-4be3-930b-7e43b9d2f317', 'Untuk Menuangkan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('d5bd929f-f589-4be3-930b-7e43b9d2f317', 'そそぐ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('d5bd929f-f589-4be3-930b-7e43b9d2f317', 'つぐ', NULL, false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d5bd929f-f589-4be3-930b-7e43b9d2f317', 'もしかして、わたしのコーラに牛にゅう注いだ？', 'Apakah kamu kebetulan menuangkan susu ke dalam minuman bersodaku?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d5bd929f-f589-4be3-930b-7e43b9d2f317', 'コウイチは、今年はAKB48をおうえんすることに全力を注いでいます。', 'Koichi mencurahkan seluruh energinya untuk mendukung AKB48 tahun ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d5bd929f-f589-4be3-930b-7e43b9d2f317', '「もう少しワインを注いでいただけますか？」「もちろん。“そこまで”って言ってくださいね。」「あ、そこまで！それくらいで結構です。有難うございます。」', '"Bisakah kamu menuangkan anggur lagi untukku?" "Tentu. Katakan saja kapan." "Ya! Itu sempurna. Terima kasih."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5f624116-736d-4388-8f40-bd28209e0945', 'vocabulary', '注文', '注文', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Anda menuangkan tulisan ke dalam formulir. Anda mengisi formulir ini untuk memesan sesuatu yang baru untuk Anda sendiri. Ini adalah permintaan formal untuk mendapatkan barang baru ini (bayangkan itu adalah sesuatu yang ingin Anda pesan saat ini, dan bayangkan diri Anda memesannya dengan menuangkan tulisan ke formulir pemesanan).', 'Anda menuangkan tulisan ke dalam formulir. Anda mengisi formulir ini untuk memesan sesuatu yang baru untuk Anda sendiri. Ini adalah permintaan formal untuk mendapatkan barang baru ini (bayangkan itu adalah sesuatu yang ingin Anda pesan saat ini, dan bayangkan diri Anda memesannya dengan menuangkan tulisan ke formulir pemesanan).') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5f624116-736d-4388-8f40-bd28209e0945', 'Pesan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5f624116-736d-4388-8f40-bd28209e0945', 'Request', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('5f624116-736d-4388-8f40-bd28209e0945', 'ちゅうもん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5f624116-736d-4388-8f40-bd28209e0945', 'スタバの注文の仕方がいまいちよく分からないんだけど。', 'Saya kurang paham cara pesan di Starbucks.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5f624116-736d-4388-8f40-bd28209e0945', 'まさか注文するのをわすれてたりしないよね。', 'Anda tidak lupa memesannya, bukan?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5f624116-736d-4388-8f40-bd28209e0945', 'それは無理な注文だが、やるっきゃない。', 'Itu permintaan yang tidak masuk akal tapi kami tidak punya pilihan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('55b31e04-9442-416d-a657-70da80237045', 'vocabulary', '味', '味', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
