INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3a161219-aaa0-45f3-84f8-d959fab0badb', 'あんまり自分を安売りすると、後で辛くなりますよ。', 'Jika Anda menjual diri Anda terlalu pendek, itu akan sulit nantinya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3a161219-aaa0-45f3-84f8-d959fab0badb', 'このジャケット、めっちゃ好きだけど、ちょっとよゆうがないんですよね。近々安売りするよていとかってないですかね？', 'Saya sangat menyukai jaket ini, tetapi tidak mampu membelinya. Apakah ada penjualan yang akan datang?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3a161219-aaa0-45f3-84f8-d959fab0badb', 'そうだよ。君に売った時にはそのテレビは壊れていたさ。でも、だからこそ安売りしたんじゃないか。', 'Ya, TV itu rusak ketika saya menjualnya kepada Anda, tapi itulah sebabnya TV itu dijual.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('85132cfa-362a-4831-9745-d50de1373232', 'vocabulary', 'お知らせ', 'お知らせ', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Ini adalah kata yang aneh, jadi Anda harus bersabar. Anda tahu bahwa 知 artinya tahu. Namun dalam kasus kata ini, apa yang Anda ketahui? Lihatlah babak kedua. らせ terdengar seperti "balapan". Jadi, Anda tahu tentang "perlombaan". Bagaimana Anda tahu tentang perlombaan ini? Anda mendapat pemberitahuan atau pemberitahuan tentang hal itu.', 'Ini adalah kata yang aneh, jadi Anda harus bersabar. Anda tahu bahwa 知 artinya tahu. Namun dalam kasus kata ini, apa yang Anda ketahui? Lihatlah babak kedua. らせ terdengar seperti "balapan". Jadi, Anda tahu tentang "perlombaan". Bagaimana Anda tahu tentang perlombaan ini? Anda mendapat pemberitahuan atau pemberitahuan tentang hal itu.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
