INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('686fdf8d-7853-4c51-9afe-64d2b87d6b25', 'Ophthalmologist', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('686fdf8d-7853-4c51-9afe-64d2b87d6b25', 'めいしゃ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('686fdf8d-7853-4c51-9afe-64d2b87d6b25', 'きのう目がいたくなって、目医者に行ったら、ものもらいだった。', 'Mata saya mulai sakit kemarin, saya berobat ke dokter mata, dan itu bintit.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('686fdf8d-7853-4c51-9afe-64d2b87d6b25', '週末も開いている目医者をさがしています。', 'Saya mencari dokter mata yang buka pada akhir pekan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('686fdf8d-7853-4c51-9afe-64d2b87d6b25', '「よお、目医者さん。もう何もかもばれているんだよ。だから、目について何も知らないふりをする必要はないぜ。」', 'Dengar, Tuan Dokter Mata. Kucing sudah keluar dari tas, jadi tidak perlu berpura-pura tidak tahu apa-apa tentang mata.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a71fc4cf-7653-4eb4-9fe5-14032019ba08', 'vocabulary', '使い方', '使い方', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Anda sudah melihat kata 使う semoga sekarang. Jika pernah, Anda pasti tahu artinya "menggunakan". Jadi, cara menggunakan sesuatu adalah cara menggunakan (alias cara menggunakan). Ini akan menjadi kata yang Anda lihat saat Anda melihat petunjuk cara menggunakan sesuatu.', 'Anda sudah melihat kata 使う semoga sekarang. Jika pernah, Anda pasti tahu artinya "menggunakan". Jadi, cara menggunakan sesuatu adalah cara menggunakan (alias cara menggunakan). Ini akan menjadi kata yang Anda lihat saat Anda melihat petunjuk cara menggunakan sesuatu.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
