INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('42e480bd-30d9-4b4d-afd3-0584125b932f', '自分的には上手にアメリカ的なスピーチができたと思ってたんだけどな。', 'Saya pribadi merasa mampu menyampaikan pidato gaya Amerika dengan cukup baik.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('42e480bd-30d9-4b4d-afd3-0584125b932f', 'コウイチの神ぴ的なえみが、こ人的にめっちゃツボなんだよね。', 'Saya pribadi menyukai senyum misterius Koichi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('42e480bd-30d9-4b4d-afd3-0584125b932f', 'トーフグ的秘密計画って一体何ですか？もう少し具体的におっしゃって頂けませんか？', 'Apa maksudmu dengan rencana rahasia seperti Tofugu? Apakah menurut Anda Anda bisa lebih spesifik?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e3f37196-7b4b-478b-80b1-b1c11b5695b3', 'vocabulary', '日本的', '日本的', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Hal-hal yang menjadi sasaran orang Jepang lebih dari sekedar orang Jepang, mereka sangat Jepang. Kata ini mungkin sulit dipahami pada awalnya, namun ada banyak hal yang dianggap hanya bahasa Jepang oleh orang Jepang. Teori-teori ini berkisar dari yang masuk akal hingga yang konyol, tetapi bagaimanapun juga, Anda akan melihatnya digambarkan sebagai 日本的.', 'Hal-hal yang menjadi sasaran orang Jepang lebih dari sekedar orang Jepang, mereka sangat Jepang. Kata ini mungkin sulit dipahami pada awalnya, namun ada banyak hal yang dianggap hanya bahasa Jepang oleh orang Jepang. Teori-teori ini berkisar dari yang masuk akal hingga yang konyol, tetapi bagaimanapun juga, Anda akan melihatnya digambarkan sebagai 日本的.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
