INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e3f37196-7b4b-478b-80b1-b1c11b5695b3', '日本的なくらしにあこがれています。', 'Saya mendambakan kehidupan ala Jepang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e3f37196-7b4b-478b-80b1-b1c11b5695b3', 'このアニメはとても日本的ですね。', 'Anime ini sangat Jepang ya?') ON CONFLICT DO NOTHING;
