INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('286ccfa9-1bd7-4f59-8d94-68c1a8297c70', '英語の発音は日本語の発音よりむずかしいと思う。', 'Menurut saya, pengucapan bahasa Inggris lebih sulit daripada pengucapan bahasa Jepang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('286ccfa9-1bd7-4f59-8d94-68c1a8297c70', 'もしこのレストランの店員も英語が話せるようだったら、今後わざわざあの店まで行かなくてすむようになるね。', 'Jika pekerja restoran ini ternyata bisa berbahasa Inggris, kita tidak perlu jauh-jauh pergi ke restoran lain lagi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('286ccfa9-1bd7-4f59-8d94-68c1a8297c70', '「僕たちは皆、英語と数学の授業が嫌いだ。」「ちょっと、一緒にしないでよ。私は両方共好きだし。」', '"Kami semua membenci kelas Bahasa Inggris dan Matematika." “Hei, bicaralah sendiri. Aku suka keduanya.”') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('484f8191-a82a-4549-888a-01ff1c84edf1', 'vocabulary', '英会話', '英会話', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Pertemuan bahasa Inggris dan berbicara satu sama lain. Ini adalah Percakapan Bahasa Inggris. Ini banyak digunakan ketika berbicara tentang "berbicara dalam bahasa Inggris" untuk belajar bahasa Inggris dan yang lainnya.', 'Pertemuan bahasa Inggris dan berbicara satu sama lain. Ini adalah Percakapan Bahasa Inggris. Ini banyak digunakan ketika berbicara tentang "berbicara dalam bahasa Inggris" untuk belajar bahasa Inggris dan yang lainnya.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
