INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f3b61e9b-41e6-4788-9a15-30d606d0952d', 'ここに日本語で文をかいて、その下に英文でやくを付けてください。', 'Silakan tulis kalimat dalam bahasa Jepang di sini dan tambahkan terjemahan bahasa Inggris di bawahnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f3b61e9b-41e6-4788-9a15-30d606d0952d', 'わたしの母は高校の英語の先生になるために、大学で英文科をそつ業したそうです。', 'Saya mendengar bahwa ibu saya lulus dari Jurusan Komposisi Bahasa Inggris di perguruan tinggi untuk menjadi guru bahasa Inggris di sekolah menengah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f3b61e9b-41e6-4788-9a15-30d606d0952d', 'ねぇ、忙しいところ悪いんだけどさ、この英文の翻訳にちょっと手こずっちゃってるんだよね。手伝ってもらえないかな？', 'Hei, maaf mengganggu Anda, tapi saya agak terjebak pada terjemahan kalimat bahasa Inggris ini. Bisakah Anda membantu saya?') ON CONFLICT DO NOTHING;
