INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('163c2b0b-f2fc-43c9-bc84-497c099611e1', 'vocabulary', '明日', '明日', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Hari yang cerah bukanlah hari ini (karena hari ini sangat buruk), melainkan hari esok, karena Anda selalu dapat memandang hari esok sebagai hari yang lebih baik dan lebih cerah.', 'Hari yang cerah bukanlah hari ini (karena hari ini sangat buruk), melainkan hari esok, karena Anda selalu dapat memandang hari esok sebagai hari yang lebih baik dan lebih cerah.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
