INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('fb2d5cc6-418e-4693-80b2-e1da345bac2f', 'vocabulary', '空車', '空車', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Ketika sebuah mobil memiliki langit di dalamnya (dan bukan, katakanlah, sekelompok orang), maka Anda bebas memberi tumpangan. Jika Anda melihat tanda ini menyala di taksi, jangan ragu untuk menghentikannya, itu akan membawa Anda ke suatu tempat. Ini adalah taksi terbuka.', 'Ketika sebuah mobil memiliki langit di dalamnya (dan bukan, katakanlah, sekelompok orang), maka Anda bebas memberi tumpangan. Jika Anda melihat tanda ini menyala di taksi, jangan ragu untuk menghentikannya, itu akan membawa Anda ke suatu tempat. Ini adalah taksi terbuka.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
