INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fb2d5cc6-418e-4693-80b2-e1da345bac2f', 'タクシーのひょうじが「空車」となっているときは、おきゃくさんはだれものっていません。', 'Saat taksi menampilkan "Taksi Terbuka", tidak ada pelanggan di dalamnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fb2d5cc6-418e-4693-80b2-e1da345bac2f', 'この辺りのコインパーキングがいつも空車なのがふしぎでしょうがない。', 'Aku jadi penasaran kenapa tempat parkir di sekitar sini selalu kosong.') ON CONFLICT DO NOTHING;
