INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('21ec6116-2174-4ce1-839c-31c88dcbea67', 'いっぽ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('21ec6116-2174-4ce1-839c-31c88dcbea67', 'ようやく、ゆめに向かって一歩ふみ出しました。', 'Saya akhirnya mengambil satu langkah maju menuju impian saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('21ec6116-2174-4ce1-839c-31c88dcbea67', '千里の道も一歩からって言うでしょ？', 'Katanya, perjalanan seribu mil dimulai dengan satu langkah, bukan?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('21ec6116-2174-4ce1-839c-31c88dcbea67', '最初の一歩を踏み出すのに勇気がいる。', 'Dibutuhkan keberanian untuk mengambil langkah pertama ke depan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6c88ceda-18b5-4497-b23c-0824e2e79753', 'vocabulary', '味方', '味方', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Cita rasa dari arah ini adalah salah satu yang ingin saya ikuti dan ikuti, bersama Anda. Anda memiliki selera yang bagus dan Anda menuju ke arah yang baik. Maukah kamu menjadi sekutuku? Saya akan menjadi pendukung Anda.', 'Cita rasa dari arah ini adalah salah satu yang ingin saya ikuti dan ikuti, bersama Anda. Anda memiliki selera yang bagus dan Anda menuju ke arah yang baik. Maukah kamu menjadi sekutuku? Saya akan menjadi pendukung Anda.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
