INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6c88ceda-18b5-4497-b23c-0824e2e79753', 'トーフグだけは、味方してくれると思ってたんだけどな。', 'Saya pikir setidaknya Tofugu akan mendukung saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6c88ceda-18b5-4497-b23c-0824e2e79753', '実は、コウイチは味方のふりをしたてきだったんだよ。', 'Sebenarnya Koichi adalah musuh yang menyamar sebagai teman.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6c88ceda-18b5-4497-b23c-0824e2e79753', 'お前は一体どっちの味方なんだ？', 'Siapa sekutumu?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ace9af80-a2be-4128-b9cf-41581fdf56f3', 'vocabulary', '天使', '天使', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Orang yang memanfaatkan surga untuk keuntungannya adalah seseorang yang berasal dari surga, seperti bidadari.', 'Orang yang memanfaatkan surga untuk keuntungannya adalah seseorang yang berasal dari surga, seperti bidadari.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
