INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ace9af80-a2be-4128-b9cf-41581fdf56f3', 'ニッカちゃん、マジ天使だわー。', 'Nikka benar-benar bidadari.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ace9af80-a2be-4128-b9cf-41581fdf56f3', 'あの天使と、少しきょりをおきたいと思っています。', 'Saya pikir saya perlu menjauhkan diri dari malaikat untuk sementara waktu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ace9af80-a2be-4128-b9cf-41581fdf56f3', '天使のように可愛い女の子に会った。', 'Saya bertemu dengan seorang gadis yang semanis malaikat.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e614c7e5-3dc2-421a-b33d-633ea9a749d7', 'vocabulary', '読者', '読者', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Seseorang yang membaca adalah seseorang yang sedang membaca. Mereka adalah pembaca (buku, blog, artikel, dll).', 'Seseorang yang membaca adalah seseorang yang sedang membaca. Mereka adalah pembaca (buku, blog, artikel, dll).') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
