INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('277dcca1-3328-48e2-97e4-52a4eda01338', '安田さんは、食べ物をおねがいします。', 'Tolong bawakan makanan, Bu Yasuda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('277dcca1-3328-48e2-97e4-52a4eda01338', 'かなしい時や、おちこんでいる時は、いつも食べ物がのどを通らなくなってしまうんです。', 'Saya selalu mempunyai masalah dengan makan setiap kali saya merasa sedih atau depresi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('277dcca1-3328-48e2-97e4-52a4eda01338', '食べ物を粗末にするとバチが当たりますよ。', 'Jika Anda menyia-nyiakan makanan, surga akan menghukum Anda.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4a33754a-f4f2-4041-849c-75a99ef2fbbe', 'vocabulary', '赤い', '赤い', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat dari merah? Wah, warnanya merah!', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat dari merah? Wah, warnanya merah!') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
