INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4a33754a-f4f2-4041-849c-75a99ef2fbbe', '赤いネクタイをください。', 'Bolehkah saya minta dasi merahnya?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4a33754a-f4f2-4041-849c-75a99ef2fbbe', '今年は赤いマニキュアがはやっています。', 'Tahun ini cat kuku merah sedang populer.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4a33754a-f4f2-4041-849c-75a99ef2fbbe', '赤いニット帽を被った女の子がスケートをしている。', 'Gadis bertopi rajut merah sedang bermain skating.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0975ad45-c90b-4954-8923-4420b7ee91e8', 'vocabulary', '売れる', '売れる', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya menjual, jadi versi verbanya adalah menjual atau dijual.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya menjual, jadi versi verbanya adalah menjual atau dijual.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
