INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0975ad45-c90b-4954-8923-4420b7ee91e8', 'このゲーム、ぜったい売れるだろ。', 'Game ini pasti akan laris manis.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0975ad45-c90b-4954-8923-4420b7ee91e8', 'その千円札、五百円でネットオークションにかけたら、よゆうで売れるっしょ。', 'Menurutku, jika kamu memasang uang seribu yen untuk lelang online, uang itu akan terjual dengan mudah seharga lima ratus yen.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0975ad45-c90b-4954-8923-4420b7ee91e8', '売れる小説の書き方を教えてあげよう。', 'Saya akan mengajari Anda cara menulis novel yang laku.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b1ac1215-ea62-42c5-a5b4-72ea70e28086', 'vocabulary', '見物', '見物', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Jika Anda mencoba melihat banyak hal sekaligus, Anda mungkin sedang jalan-jalan atau menonton. Ini juga bisa merujuk pada orang yang melakukan tindakan tersebut, jadi terkadang bisa berarti wisatawan juga.', 'Jika Anda mencoba melihat banyak hal sekaligus, Anda mungkin sedang jalan-jalan atau menonton. Ini juga bisa merujuk pada orang yang melakukan tindakan tersebut, jadi terkadang bisa berarti wisatawan juga.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
