INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b1ac1215-ea62-42c5-a5b4-72ea70e28086', 'おもしろそうだから、見物してみましょう。', 'Tampaknya menyenangkan, jadi mari kita lihat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b1ac1215-ea62-42c5-a5b4-72ea70e28086', 'オフィスのまどから、クリスマスパレードを見物しました。', 'Kami menyaksikan parade Natal dari jendela kantor.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b1ac1215-ea62-42c5-a5b4-72ea70e28086', '母ちゃんなら、東京見物に出かけたぜ。', 'Ibu pasti pergi jalan-jalan ke Tokyo.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d1dd8f1c-6ec5-4ce7-acfd-666b7eb32686', 'vocabulary', '大空', '大空', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Hal besar di langit adalah surga. Surga tempat burung dan pesawat terbang, bukan surga yang akan kamu datangi setelah kamu mati jika kamu benar-benar baik.', 'Hal besar di langit adalah surga. Surga tempat burung dan pesawat terbang, bukan surga yang akan kamu datangi setelah kamu mati jika kamu benar-benar baik.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
